function verify_dalga26_alpha(output_dir)
  % UNVERIFIED native PNG pixel probe. Run only in an orchestrator fresh copy.
  % The cases compare same-size geometry and print observed pixels; they do
  % not assert that data-mapped alpha has a particular Octave interpretation.
  if nargin<1||isempty(output_dir),error('Pass an orchestrator-owned output directory.');end
  if ~exist(output_dir,'dir'),mkdir(output_dir);end
  cases={...
    'patch scalar face alpha','patch',{'facealpha',.5},[.5 .5];...
    'patch flat face alpha','patch',{'facealpha','flat','facevertexalphadata',.5},[.5 .5];...
    'patch interpolated face alpha','patch',{'facealpha','interp','facevertexalphadata',[.5;.5;.5;.5]},[.5 .5];...
    'patch direct double face alpha','patch',{'facealpha','flat','facevertexalphadata',33,'alphadatamapping','direct'},[.5 .5];...
    'patch scaled double face alpha','patch',{'facealpha','flat','facevertexalphadata',.5,'alphadatamapping','scaled'},[.5 .5];...
    'patch direct uint8 face alpha','patch',{'facealpha','flat','facevertexalphadata',uint8(33),'alphadatamapping','direct'},[.5 .5];...
    'surface scalar face alpha','surface',{'facealpha',.5},[.5 .5];...
    'surface flat face alpha','surface',{'facealpha','flat','alphadata',.5*ones(2)},[.5 .5];...
    'surface interpolated face alpha','surface',{'facealpha','interp','alphadata',.5*ones(2)},[.5 .5];...
    'surface direct uint8 face alpha','surface',{'facealpha','flat','alphadata',uint8(33*ones(2)),'alphadatamapping','direct'},[.5 .5];...
    'surface scaled face alpha','surface',{'facealpha','flat','alphadata',.5*ones(2),'alphadatamapping','scaled'},[.5 .5];...
    'patch scalar edge alpha','patch_edge',{'edgealpha',.5},[.5 .02];...
    'surface scalar edge alpha','surface_edge',{'edgealpha',.5},[.5 .02]...
  };
  for k=1:rows(cases)
    f=figure('visible','off','position',[0 0 160 160],'color',[1 1 1]);
    set(f,'alphamap',linspace(0,1,64)');
    ax=axes('parent',f,'position',[0 0 1 1],'color',[1 1 1]);
    kind=cases{k,2};
    if strncmp(kind,'patch',5)
      edge='none';linewidth=1;if strcmp(kind,'patch_edge'),edge=[0 0 0];linewidth=6;end
      h=patch('parent',ax,'vertices',[0 0 1;1 0 1;1 1 1;0 1 1],...
        'faces',1:4,'facecolor',[.2 .6 .8],'edgecolor',edge,'linewidth',linewidth);
    else
      edge='none';linewidth=1;if strcmp(kind,'surface_edge'),edge=[0 0 0];linewidth=6;end
      h=surf(ax,[0 1],[0 1],ones(2),ones(2),...
        'facecolor',[.2 .6 .8],'edgecolor',edge,'linewidth',linewidth);
    endif
    props=cases{k,3};
    for j=1:2:numel(props),set(h,props{j},props{j+1});endfor
    set(ax,'xlim',[0 1],'ylim',[0 1],'zlim',[0 2]);axis(ax,'off');view(ax,2);drawnow();
    path=fullfile(output_dir,sprintf('dalga26_alpha_%02d.png',k));
    print(f,path,'-dpng','-r100');
    rgb=d26_read_png_rgb(path);
    point=cases{k,4};
    col=max(1,min(columns(rgb),round(1+point(1)*(columns(rgb)-1))));
    row=max(1,min(rows(rgb),round(rows(rgb)-point(2)*(rows(rgb)-1))));
    observed=reshape(rgb(row,col,1:3),1,3);
    fprintf('D26 NATIVE ALPHA PNG: %s; rgb=[%d %d %d]; pixel=%d,%d; file=%s\n',...
      cases{k,1},observed(1),observed(2),observed(3),row,col,path);
    close(f);
  endfor
endfunction
